//! 🧪️ The actual producer carries genuine original directory custody across one changed immutable path.
#[path="../../../../../../♻️retirement/🧪️tests/⏱️work/🦀️.rs"]mod close_work_policy;
use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::named_edit::KeyPreservingPersistentSet;
#[path="../../🌳️root/🛬️receive/🧪️tests/🦀️.rs"]mod receiving;
#[derive(semio_framework_value_derive::RetireOwned)]#[value(crate="crate")]struct TransferRow{key:String,payload:usize}
impl Clone for TransferRow{fn clone(&self)->Self{panic!("key-preserving changes must share every original unaddressed row")}}
fn transfer_key(row:&TransferRow)->&str{&row.key}
fn root(keys:&[String])->PersistentList<TransferRow>{let mut builder=PersistentListBuilder::new(keys.len(),grant(PersistentListBuilder::<TransferRow>::constructor_demand())).unwrap().unwrap();for(rank,text)in keys.iter().enumerate(){while !builder.accepts_row(){let d=builder.demand().unwrap();exact(||builder.advance(grant(d)).unwrap(),|s|s.progress());}let mut row=Some(SealedShared::admit(TransferRow{key:text.to_owned(),payload:rank},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<TransferRow>::birth_bytes(),depth:1,..Default::default()})).map_err(|(e,_)|e).unwrap().0);let d=builder.adopt_demand().unwrap();exact(||builder.adopt(&mut row,grant(d)).unwrap().unwrap(),|p|*p);}let d=builder.finish_demand().unwrap();builder.finish(grant(d)).unwrap().unwrap();while !builder.output_ready(){let d=builder.demand().unwrap();exact(||builder.advance(grant(d)).unwrap(),|s|s.progress());}let d=builder.take_demand().unwrap();let root=builder.take(grant(d)).unwrap().unwrap().0;builder.begin_close();let mut close_work=close_work_policy::Work::new();while !builder.terminal_is_empty(){let d=builder.close_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let(step,..)=exact(||builder.close_step(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}).unwrap(),|s|s.progress());assert!(step.progress().fits(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}));close_work.observe(step.progress()==Default::default()&&!builder.terminal_is_empty()&&builder.close_demand(4096).unwrap()==d);}root}
fn close_owner(owner:&mut KeyPreservingPersistentSet<TransferRow>,totals:&mut(usize,usize)){owner.begin_close();let mut close_work=close_work_policy::Work::new();while !owner.terminal_is_empty(){let d=owner.close_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");assert!(d.copy_bytes<=4096,"controlled producer close exceeds fixed metadata budget");for denied in denies(d){let(s,bytes)=heap(||owner.close_step(denied).unwrap());assert_eq!(bytes,(0,0));assert_eq!(s.progress(),Default::default());assert_eq!(owner.close_demand(4096).unwrap(),d);}let(step,b,r)=exact(||owner.close_step(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}).unwrap(),|s|s.progress());totals.0+=b;totals.1+=r;assert!(step.progress().fits(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}));close_work.observe(step.progress()==Default::default()&&!owner.terminal_is_empty()&&owner.close_demand(4096).unwrap()==d);}}
fn close_candidate(source:&mut RetainedCloneSource<PersistentList<TransferRow>>,totals:&mut(usize,usize)){let mut close_work=close_work_policy::Work::new();while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let(step,b,r)=exact(||source.close_step(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}).unwrap(),|s|s.progress());totals.0+=b;totals.1+=r;assert!(step.progress().fits(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}));close_work.observe(step.progress()==Default::default()&&!source.terminal_is_empty()&&source.next_close_demand(4096).unwrap()==d);}}
fn run(keys:Vec<String>,rank:usize,replacement:String,accepted:bool,body:usize,cut:Option<usize>){
 let mut original=source(root(&keys));let input=PersistentRankedKeys{original:original.borrow(),key:transfer_key};let mut index=admit(&input);let directory=index.order().as_ptr();let addresses=(0..keys.len()).map(|i|input.original.get().get(i).unwrap()as*const TransferRow).collect::<Vec<_>>();let mut authored=source(SealedShared::admit(TransferRow{key:replacement,payload:999},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<TransferRow>::birth_bytes(),depth:1,..Default::default()})).map_err(|(e,_)|e).unwrap().0);let authored_address=authored.borrow().get().get()as*const TransferRow;let d=index.project_demand(&input).unwrap();let mut slot=Some(index.project(&input,grant(d)).unwrap().unwrap().0);let d=KeyPreservingPersistentSet::<TransferRow>::constructor_demand();assert!(d.copy_bytes<=4096);for denied in denies(d){let(v,bytes)=heap(||KeyPreservingPersistentSet::new(rank,transfer_key,&mut slot,denied).unwrap());assert!(v.is_none());assert!(slot.is_some());assert_eq!(bytes,(0,0));}let((mut owner,_),b,r)=exact(||KeyPreservingPersistentSet::new(rank,transfer_key,&mut slot,grant(d)).unwrap().unwrap(),|(_,p)|*p);assert!(slot.is_none());let mut totals=(b,r);let mut turns=0;
 while !owner.output_ready()&&!owner.refused()&&cut.is_none_or(|cut|turns<cut){let d=owner.demand(input.original,authored.borrow(),body).unwrap();assert!(d.copy_bytes<=4096,"producer exceeds fixed metadata plus key page budget");for denied in denies(d){let(s,bytes)=heap(||owner.advance(input.original,authored.borrow(),denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(owner.demand(input.original,authored.borrow(),body).unwrap(),d);}let(result,b,r)=exact(||owner.advance(input.original,authored.borrow(),grant(d)),|s|s.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress()));totals.0+=b;totals.1+=r;if let Err(e)=result{assert_eq!(e.kind,ValueRefusalKind::InvalidValue);assert!(owner.refused());}turns+=1;assert!(turns<1000000);}
 if cut.is_none(){assert_eq!(owner.output_ready(),accepted);assert_eq!(owner.refused(),!accepted);if accepted{let d=owner.take_demand().unwrap();for denied in denies(d){assert!(owner.take(denied).unwrap().is_none());}let(((mut candidate,mut transferred),_),b,r)=exact(||owner.take(grant(d)).unwrap().unwrap(),|(_,p)|*p);totals.0+=b;totals.1+=r;let next=PersistentRankedKeys{original:candidate.borrow(),key:transfer_key};assert_eq!(transferred.order().as_ptr(),directory);transferred.check_source(&next).unwrap();assert!(index.check_source(&next).is_err());assert!(transferred.check_source(&input).is_err());for i in 0..keys.len(){let old=input.original.get().get(i).unwrap();let new=next.original.get().get(i).unwrap();assert_eq!(old as*const TransferRow,addresses[i]);if i==rank{assert_eq!(new as*const TransferRow,authored_address);assert_eq!(new.payload,999);}else{assert_eq!(new as*const TransferRow,addresses[i]);assert_eq!(new.payload,i);}}assert_eq!(lookup(&next,&transferred,&keys[rank]).0,Some(rank));let mut candidate_slot=Some(candidate);let mut index_slot=Some(transferred);let d=crate::NamedPersistentRoot::<TransferRow>::constructor_demand();for denied in denies(d){let(value,bytes)=heap(||crate::NamedPersistentRoot::admit_parts(&mut candidate_slot,&mut index_slot,transfer_key,denied).unwrap());assert!(value.is_none());assert!(candidate_slot.is_some()&&index_slot.is_some());assert_eq!(bytes,(0,0));}let((mut preparation,_),b,r)=exact(||crate::NamedPersistentRoot::admit_parts(&mut candidate_slot,&mut index_slot,transfer_key,grant(d)).unwrap().unwrap(),|(_,p)|*p);totals.0+=b;totals.1+=r;assert!(candidate_slot.is_none()&&index_slot.is_none());while !preparation.output_ready(){let d=preparation.demand(4096).unwrap();for denied in denies(d){let(s,bytes)=heap(||preparation.advance(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));}let(_,b,r)=exact(||preparation.advance(grant(d)).unwrap(),|s|s.progress());totals.0+=b;totals.1+=r;}let d=preparation.take_demand().unwrap();let((named,_),b,r)=exact(||preparation.take(grant(d)).unwrap().unwrap(),|(_,p)|*p);totals.0+=b;totals.1+=r;assert!(preparation.terminal_is_empty());assert_eq!(heap(||drop(preparation)).1,(0,0));let d=named.project_index_demand().unwrap();let((mut alias,_),b,r)=exact(||named.project_index(grant(d)).unwrap().unwrap(),|(_,p)|*p);totals.0+=b;totals.1+=r;assert_eq!(lookup(&named.ranked().unwrap(),&alias,&keys[rank]).0,Some(rank));let d=RetainedOwnedProjection::<PersistentList<TransferRow>>::constructor_demand();for denied in denies(d){let(result,bytes)=heap(||named.project_rows(denied));assert!(result.is_err());assert_eq!(bytes,(0,0));}let((mut reader,_),b,r)=exact(||named.project_rows(grant(d)).unwrap(),|(_,p)|*p);assert!(reader.matches_source(named.ranked().unwrap().original));totals.0+=b;totals.1+=r;let d=RetirementDemand{capacity_bytes:SealedShared::<crate::NamedPersistentRoot<TransferRow>>::birth_bytes(),depth:1,..Default::default()};let((sealed,_),b,r)=exact(||SealedShared::admit(named,SharedIssuer::owned(),grant(d)).map_err(|(e,_)|e).unwrap(),|(_,p)|*p);totals.0+=b;totals.1+=r;let mut close=ControlledRetirement::new(sealed).map_err(|(e,_)|e).unwrap();let mut close_work=close_work_policy::Work::new();while !close.terminal_is_empty(){let d=close.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let(step,b,r)=exact(||close.step(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}).unwrap(),|s|s.progress());totals.0+=b;totals.1+=r;assert!(step.progress().fits(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}));close_work.observe(step.progress()==Default::default()&&!close.terminal_is_empty()&&close.next_demand(4096).unwrap()==d);}assert_eq!(heap(||drop(close)).1,(0,0));let live=PersistentRankedKeys{original:reader.borrow().unwrap(),key:transfer_key};assert_eq!(lookup(&live,&alias,&keys[rank]).0,Some(rank));assert_eq!(live.original.get().get(rank).unwrap()as*const TransferRow,authored_address);let(b,r)=close_index(&mut alias);totals.0+=b;totals.1+=r;let mut close_work=close_work_policy::Work::new();while !reader.terminal_is_empty(){let d=reader.close_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let(step,b,r)=exact(||reader.close_step(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}).unwrap(),|s|s.progress());totals.0+=b;totals.1+=r;assert!(step.progress().fits(RetainedCloneGrant{maximum_copy_bytes:4096,..grant(d)}));close_work.observe(step.progress()==Default::default()&&!reader.terminal_is_empty()&&reader.close_demand(4096).unwrap()==d);}assert_eq!(heap(||drop(reader)).1,(0,0));}}
 close_owner(&mut owner,&mut totals);assert_eq!(totals.0,totals.1,"actual producer, candidate source and transferred directory ledger must settle without rebasing");assert_eq!(heap(||drop(owner)).1,(0,0));close_index(&mut index);close_source(&mut original);close_source(&mut authored);
}
#[test]
fn key_preserving_persistent_producer_transfers_original_directory_and_all_paid_cuts(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/♻️transfer/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for body in fixture["bodyBytes"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain(std::iter::once(None)){run(row["keys"].as_array().unwrap().iter().map(|key|key.as_str().unwrap().to_owned()).collect(),row["rank"].as_u64().unwrap()as usize,row["replacement"].as_str().unwrap().to_owned(),row["admitted"].as_bool().unwrap(),body.as_u64().unwrap()as usize,cut);}}}let keys=(0..257).map(|rank|format!("key{rank:08}")).collect::<Vec<_>>();run(keys.clone(),128,keys[128].clone(),true,4096,None);}
#[test]
fn key_preserving_persistent_producer_checks_complete_original_utf8_and_foreign_sources(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🔑️named/📇️index/♻️transfer/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let prefix="x".repeat(fixture["prefixLength"].as_u64().unwrap()as usize);for suffix in ["é","é"]{run(vec![format!("{prefix}é")],0,format!("{prefix}{suffix}"),suffix=="é",1,None);}let keys=vec!["A".to_owned()];let mut original=source(root(&keys));let mut foreign=source(root(&keys));let input=PersistentRankedKeys{original:original.borrow(),key:transfer_key};let mut index=admit(&input);let d=index.project_demand(&input).unwrap();let mut slot=Some(index.project(&input,grant(d)).unwrap().unwrap().0);let((mut owner,_),born,released)=exact(||KeyPreservingPersistentSet::new(0,transfer_key,&mut slot,grant(KeyPreservingPersistentSet::<TransferRow>::constructor_demand())).unwrap().unwrap(),|(_,p)|*p);let mut authored=source(SealedShared::admit(TransferRow{key:"A".to_owned(),payload:99},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<TransferRow>::birth_bytes(),depth:1,..Default::default()})).map_err(|(e,_)|e).unwrap().0);let(result,bytes)=heap(||owner.demand(foreign.borrow(),authored.borrow(),4096));assert!(result.is_err());assert_eq!(bytes,(0,0));let mut totals=(born,released);close_owner(&mut owner,&mut totals);assert_eq!(totals.0,totals.1);close_index(&mut index);close_source(&mut original);close_source(&mut foreign);close_source(&mut authored);}
